final class DirView: Dir {
    private let raw: Dir
    private let m: Membrane

    func open(_ path: String) throws -> File {
        guard !m.revoked else { throw MembraneError.revoked }
        let f = try raw.open(path)
        return try m.wrap(f)                 // wrap the way out
    }
}

