@dynamicMemberLookup
final class DirView {
    private let raw: Dir
    private let m: Membrane

    subscript<T>(dynamicMember key: WritableKeyPath<Dir, T>) -> T {
        get { m.wrap(raw[keyPath: key]) }              // wrap the way out
        set {
            guard !m.revoked else { fatalError("revoked") }
            raw[keyPath: key] = newValue                // wrap the way in
        }
    }
}
